description:
Write an async generator `batches(source, size)` that takes any async iterable (or ordinary iterable) and yields arrays of `size` items, with a shorter last batch if items are left over. A `size` below 1 throws a `RangeError` when iteration starts.

```javascript
for await (const b of batches(numbers(1, 7), 3)) console.log(b);
// [1, 2, 3]  [4, 5, 6]  [7]
```

starter.solution.js:
async function* batches(source, size) {
  for await (const item of source) yield [item];
}

solution.solution.js:
async function* batches(source, size) {
  if (size < 1) throw new RangeError("size must be at least 1");
  let batch = [];
  for await (const item of source) {
    batch.push(item);
    if (batch.length === size) {
      yield batch;
      batch = [];
    }
  }
  if (batch.length) yield batch;
}

unitTests:
async function* numbers(from, to) {
  for (let i = from; i <= to; i++) {
    await null;
    yield i;
  }
}
async function collect(it) {
  const out = [];
  for await (const x of it) out.push(x);
  return out;
}

test("groups into batches", async () => {
  checkEq(await collect(batches(numbers(1, 7), 3)), [[1, 2, 3], [4, 5, 6], [7]]);
});

test("exact multiple has no empty batch", async () => {
  checkEq(await collect(batches(numbers(1, 4), 2)), [[1, 2], [3, 4]]);
});

test("works with an ordinary array", async () => {
  checkEq(await collect(batches(["a", "b", "c"], 5)), [["a", "b", "c"]]);
});

test("nothing in, nothing out", async () => {
  checkEq(await collect(batches([], 2)), []);
});

test("bad size", async () => {
  let caught = null;
  try {
    await collect(batches([1], 0));
  } catch (e) {
    caught = e;
  }
  check(caught instanceof RangeError);
});

